def osa(script,timeout=20):
    p=subprocess.run(
        ["/usr/bin/osascript","-e",script],
        capture_output=True,text=True,timeout=timeout
    )
    if p.returncode:
        raise RuntimeError((p.stderr or p.stdout).strip())
    return p.stdout.rstrip()

def b64js(js):
    return base64.b64encode(js.encode()).decode()

SCAN_JS=r'''(() => {
 const t=document.body?.innerText||document.body?.textContent||"";
 const re=/\[\[CHATLOCAL_V4_REQUEST\]\]([A-Za-z0-9_-]+)\[\[\/CHATLOCAL_V4_REQUEST\]\]/g;
 const a=[];
 let m;
 while((m=re.exec(t))) a.push(m[1]);
 return JSON.stringify(a);
})()'''

def scan_tabs():
    b=b64js(SCAN_JS)
    sc=f'''
tell application "Google Chrome"
 set outText to ""
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   try
    set u to URL of tab ti of window wi
    if u starts with "https://chatgpt.com/" then
     set r to execute tab ti of window wi javascript "eval(atob('{b}'))"
     set outText to outText & wi & "::CHATLOCALV4::" & ti & "::CHATLOCALV4::" & u & "::CHATLOCALV4::" & r & linefeed
    end if
   end try
  end repeat
 end repeat
 return outText
end tell
'''
    out=osa(sc)
    rows=[]
    for line in out.splitlines():
        p=line.split("::CHATLOCALV4::",3)
        if len(p)!=4:
            continue
        try:
            wi=int(p[0]); ti=int(p[1]); arr=json.loads(p[3])
        except Exception:
            continue
        rows.append((wi,ti,p[2],arr if isinstance(arr,list) else []))
    return rows

