def health():
    try:
        with urllib.request.urlopen(BASE+"/health",timeout=2) as r:
            return json.load(r)
    except Exception as e:
        return {"ok":False,
                "error":type(e).__name__,
                "message":str(e)}

def daemon_error_tail():
    p=RUN/"daemon.err.log"
    if not p.exists():
        return ""
    try:
        return p.read_text(errors="ignore")[-4000:]
    except Exception:
        return ""

def request_local(req):
    try:
        tok=token()
    except Exception as e:
        return {
            "ok":False,
            "id":req.get("id"),
            "error":"TokenError",
            "message":str(e)
        }

    headers={
        "Content-Type":"application/json",
        "X-CopyToLive-Token":tok
    }

    def enqueue():
        q=urllib.request.Request(
            BASE+"/v1/enqueue",
            data=json.dumps(req,separators=(",",":")).encode(),
            method="POST",
            headers=headers
        )
        with urllib.request.urlopen(q,timeout=10) as r:
            return json.load(r)

    try:
        en=enqueue()
    except Exception:
        kick_daemon()
        time.sleep(2)
        try:
            en=enqueue()
        except Exception as e:
            return {
                "ok":False,
                "id":req.get("id"),
                "error":type(e).__name__,
                "message":str(e),
                "health":health(),
                "daemon_err_tail":daemon_error_tail()
            }

    qid=str(en.get("id") or req.get("id"))
    deadline=time.time()+180

    while time.time()<deadline:
        try:
            q=urllib.request.Request(
                BASE+"/v1/result/"+urllib.parse.quote(qid,safe=""),
                headers={"X-CopyToLive-Token":tok}
            )
            with urllib.request.urlopen(q,timeout=10) as r:
                st=json.load(r)
            if st.get("status") in ("done","error"):
                return st.get("result") or st
        except Exception:
            pass
        time.sleep(.12)

    return {
        "ok":False,
        "id":req.get("id"),
        "error":"Timeout"
    }

def decode_req(s):
    try:
        s=s+"="*((4-len(s)%4)%4)
        x=json.loads(base64.urlsafe_b64decode(s).decode())
        if not isinstance(x,dict):
            return None
        if not x.get("id") or not x.get("op"):
            return None
        return x
    except Exception:
        return None

try:
    state=json.loads(STATE.read_text()) if STATE.exists() else {}
except Exception:
    state={}

seen=set(state.get("seen") or [])

log("V4_START",os.getpid())

# Recover daemon at startup, but V4 itself stays alive even if daemon fails.
kick_daemon()

while True:
    try:
        for wi,ti,url,payloads in scan_tabs():
            for p in payloads:
                req=decode_req(p)
                if not req:
                    continue

                rid=str(req["id"])
                if rid in seen:
                    continue

                log("CAPTURE",rid,url)
                result=request_local(req)

                msg=(
                    "CHAT_LOCAL_RESULT "+rid+"\n"+
                    json.dumps(result,ensure_ascii=False)
                )

                sr=send_to_tab(wi,ti,msg)
                log("SEND",rid,sr)

                if sr=="SCHEDULED":
                    seen.add(rid)
                    STATE.write_text(
                        json.dumps(
                            {"schema":4,
                             "seen":list(seen)[-5000:]},
                            ensure_ascii=False
                        )
                    )

    except Exception as e:
        log("LOOP_ERROR",type(e).__name__,str(e))

    time.sleep(.65)
